CREATE TABLE "public"."foods" (
  "id"              integer                     GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"            text                        NOT NULL,
  "quantity"        integer                     NOT NULL,
  "expiration_date" timestamp without time zone,
  CONSTRAINT "foods_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."foods"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Foods are public" ON "public"."foods"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

REVOKE ALL ON SEQUENCE "public"."foods_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."foods_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."foods_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."foods_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."foods_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."foods_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."foods_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."foods_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."foods" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."foods" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."foods" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."foods" TO "service_role";
